#[cfg(test)]
mod tests {
    use super::*;

    fn sorted(mut v: Vec<i32>) -> Vec<i32> {
        v.sort();
        v
    }

    #[test]
    fn basic() {
        assert_eq!(sorted(top_k_frequent(&[5, 5, 5, 2, 2, 9], 2)), vec![2, 5]);
    }

    #[test]
    fn single() {
        assert_eq!(top_k_frequent(&[7], 1), vec![7]);
    }

    #[test]
    fn all_values() {
        assert_eq!(sorted(top_k_frequent(&[1, 2, 2, 3, 3, 3], 3)), vec![1, 2, 3]);
    }

    #[test]
    fn negatives() {
        assert_eq!(sorted(top_k_frequent(&[-1, -1, 4, 4, 4, 0], 2)), vec![-1, 4]);
    }

    #[test]
    fn large() {
        let mut nums = Vec::new();
        for v in 0..1000 {
            for _ in 0..=v {
                nums.push(v);
            }
        }
        assert_eq!(sorted(top_k_frequent(&nums, 3)), vec![997, 998, 999]);
    }
}
